import { _decorator, Component, Node, director } from 'cc';
import { EventBus, GameEvents } from './EventBus';
const { ccclass, property } = _decorator;

export enum GameState {
    Loading,
    Playing,
    Paused,
    Dialog,
    GameOver,
}

@ccclass('GameManager')
export class GameManager extends Component {
    private static _instance: GameManager | null = null;
    public static get instance(): GameManager { return GameManager._instance!; }

    public state: GameState = GameState.Loading;

    public playerNode: Node | null = null;

    onLoad() {
        if (GameManager._instance && GameManager._instance !== this) {
            this.node.destroy();
            return;
        }
        GameManager._instance = this;
        director.addPersistRootNode(this.node);
    }

    setState(s: GameState) {
        this.state = s;
        if (s === GameState.Paused) director.getScheduler().setTimeScale(0);
        else if (s === GameState.Playing) director.getScheduler().setTimeScale(1);
    }

    notify(msg: string) {
        EventBus.emit(GameEvents.NOTIFICATION, msg);
        console.log('[Notify]', msg);
    }

    onDestroy() {
        if (GameManager._instance === this) GameManager._instance = null;
    }
}